def signal(obs):
    n=20
    a_mid = obs.hist('A','mid', n+1)
    if a_mid is None or len(a_mid)<n+1 or np.isnan(a_mid).any():
        return {}
    ret = a_mid[-1] - a_mid[0]
    # normalize by typical move: vol per step ~1.6, so n steps vol ~ 1.6*sqrt(n) ~7, but trending bigger ~100 range
    # scale: clip ret to [-20,20] -> signal [-1,1]
    sig = ret / 20.0
    sig = max(-1, min(1, sig))
    # Prefer low-fee venue A, keep A.X flat
    return {'A': float(sig)}

