def signal(obs):
    # simple A momentum 20 step
    a_mid = obs.hist('A','mid', 60)
    if len(a_mid) < 60 or np.isnan(a_mid[-1]) or np.isnan(a_mid[-21]):
        return {}
    # past 20 return
    past = a_mid[-1] - a_mid[-21]
    # scale: vol ~1.6 per step, 20-step vol ~ 1.6*sqrt20 ~7.1
    # target = clip(past / 15)
    t = past / 15.0
    t = max(-1, min(1, t))
    # apply only to A, hedge? keep others flat
    return {'A': float(t)}

def signal(obs):
    # Try combined momentum + imbalance for A which both strong
    a_mid = obs.hist('A','mid',61)
    a_imb = obs.last('A','imbalance')
    if len(a_mid)<61 or np.isnan(a_mid[-1]) or np.isnan(a_imb):
        return {}
    past20 = a_mid[-1]-a_mid[-21]
    t_mom = max(-1,min(1,past20/12.0))
    t_imb = max(-1,min(1,a_imb*1.5))
    # blend: momentum weight 0.7 imbalance 0.3 (based on IC 0.65 vs 0.10 -> momentum dominates)
    t = 0.7*t_mom + 0.3*t_imb
    # Also test B imbalance separately maybe adds?
    b_imb = obs.last('B','imbalance')
    tB = 0
    if not np.isnan(b_imb):
        tB = max(-1,min(1,b_imb*1.2))*0.6
    c_imb = obs.last('C','imbalance')
    tC = 0
    if not np.isnan(c_imb):
        tC = max(-1,min(1,c_imb*1.2))*0.4
    res = {'A': float(t)}
    if abs(tB)>0.05:
        res['B'] = float(tB)
    if abs(tC)>0.05:
        res['C'] = float(tC)
    return res

def signal(obs):
    # A momentum 20+50 blend - strongest IC in visible era (0.65-0.73)
    try:
        a = obs.hist('A', 'mid', 60)
        if a is None or len(a) < 55:
            return {}
        # check NaN in recent window
        if np.isnan(a[-1]) or np.isnan(a[-21]) or np.isnan(a[-51]):
            return {}
        past20 = float(a[-1] - a[-21])
        past50 = float(a[-1] - a[-51])
        # weighted blend: 60% 20-step, 40% 50-step (both highly predictive)
        sig = 0.6 * past20 + 0.4 * past50
        # scale: 20-step vol ~7, 50-step vol ~11, sig typical ~ +/-10-15
        # map ~15 cents -> target 1.0
        t = sig / 20.0
        if t > 1.0:
            t = 1.0
        elif t < -1.0:
            t = -1.0
        # small smoothing via state to reduce turnover
        prev = obs.state.get('prev_A', 0.0)
        # exponential smoothing 0.7 new, 0.3 old to avoid whipsaw paying spread
        t_smooth = 0.7 * t + 0.3 * prev
        obs.state['prev_A'] = float(t_smooth)
        # trade cheapest venue A (0 fee); A.X is same underlying but 3bps fee, avoid
        return {'A': float(t_smooth)}
    except Exception:
        return {}

