# return autocorr at multiple horizons
for a in ['A','B','C','IDX','A.X','B.X','C.X']:
    m = H[a]['mid']
    out = {}
    for h in [1,5,10,20,50]:
        # h-step returns
        r = m[h:] - m[:-h]
        # need aligned; compute autocorr lag h (non-overlapping-ish but use all)
        r1 = r[:-h]
        r2 = r[h:]
        mask = ~(np.isnan(r1)|np.isnan(r2))
        if mask.sum()>20:
            c = float(np.corrcoef(r1[mask], r2[mask])[0,1])
        else:
            c = float('nan')
        out['h'+str(h)] = c
    res[a] = out
result = res

