# Past return -> future return predictability
for a in ['A','A.X','B','C','IDX']:
    m = H[a]['mid']
    out = {}
    for past in [10,20,50]:
        for fut in [10,20,50]:
            # past return ending now vs future return starting now, sampled every 10 to reduce overlap bias? use all
            # align: past[i] = m[i]-m[i-past], fut[i]=m[i+fut]-m[i]
            n = len(m)
            pr = m[past:n-fut] - m[:n-fut-past]
            fr = m[past+fut:] - m[past:n-fut]
            mask = ~(np.isnan(pr)|np.isnan(fr))
            if mask.sum()>30:
                c = float(np.corrcoef(pr[mask], fr[mask])[0,1])
            else:
                c = float('nan')
            out['p'+str(past)+'f'+str(fut)] = round(c,3)
    res[a]=out
result = res

