def signal(obs):
    a = obs.hist('A', 'mid', 30)
    if len(a) < 20 or np.isnan(a).any():
        return {}
    r10 = a[-1] - a[-11]
    # scale: std ~5.3, use threshold
    t = max(-1.0, min(1.0, r10 / 10.0))
    # deadzone to reduce turnover
    if abs(t) < 0.2:
        t = 0.0
    return {'A': float(t)}

def signal(obs):
    out = {}
    # A momentum, trade cheaper venue? A has 0 fee, A.X 3bps. Use A only (same fair value, separate books but mid nearly same; engine trades per-asset targets though).
    # Actually A and A.X same stock: if we want long exposure pick cheaper venue A. Short exposure pick... both same? Use A only.
    a = obs.hist('A', 'mid', 30)
    if len(a) >= 20 and not bool(np.isnan(a).any()):
        r10 = a[-1] - a[-11]
        t = max(-1.0, min(1.0, r10 / 10.0))
        if abs(t) < 0.2:
            t = 0.0
        out['A'] = float(t)
    # B imbalance mean-reversion? B imb positively predicts fwd -> momentum on imbalance
    for asset in ['B','C']:
        imb = obs.hist(asset, 'imbalance', 6)
        if len(imb) >= 5 and not bool(np.isnan(imb).any()):
            m = float(np.mean(imb[-5:]))
            t = max(-1.0, min(1.0, m * 2.0))
            if abs(t) < 0.15:
                t = 0.0
            out[asset] = float(t)
    return out

def signal(obs):
    out = {}
    for asset in ['A', 'A.X']:
