def momentum_corr(asset,lookback,horizon):
    price=H[asset]['mid']
    n=len(price)
    past=np.full(n,np.nan)
    fut=np.full(n,np.nan)
    for i in range(lookback,n):
        past[i]=price[i]-price[i-lookback]
    for i in range(n-horizon):
        fut[i+horizon]=price[i+horizon]-price[i]
    mask=~np.isnan(past)&~np.isnan(fut)
    if np.sum(mask)<2:
        return None
    return float(np.corrcoef(past[mask],fut[mask])[0,1])

