def signal(obs):
    def px(a):
        try:
            v = obs.last(a, 'mid')
        except Exception:
            v = float('nan')
        return v
    A = px('A'); B = px('B'); C = px('C'); I = px('IDX')
    if not (A==A and B==B and C==C and I==I):
        return {}
    syn = 0.3333*A + 0.6667*B + 0.1667*C
    prem = I - syn
    dz = 8.0
    sc = 20.0
    if abs(prem) < dz:
        s = 0.0
    else:
        s = -(prem - dz*(1 if prem>0 else -1)) / sc
        if s > 1: s = 1
        if s < -1: s = -1
    return {'IDX': s, 'A': -s*0.3333, 'B': -s*0.6667, 'C': -s*0.1667}

