    out = {}
    for a in ['A','B','C']:
        try:
            mids = obs.hist(a, 'mid', 60)
        except Exception:
            continue
        if len(mids) < 60:
            continue
        p0 = mids[0]; p1 = mids[-1]
        if not (p0==p0 and p1==p1 and p0>0):
            continue
        ret = p1 - p0  # ~50-step past (60 len)
        # scale by vol: use sd estimate
        # deadzone 6c, scale 30c for A/B, C bigger
        scale = 30.0 if a in ('A','B') else 80.0
        dz = 6.0 if a in ('A','B') else 15.0
        if abs(ret) < dz:
            out[a] = 0.0
        else:
            s = (abs(ret)-dz)/scale
            if s>1: s=1
            out[a] = s if ret>0 else -s
