def eval_pnl(m, lag, thr, horizon=50):
    past = m[lag: -horizon] - m[:-lag-horizon]
    fut = m[lag+horizon:]-m[lag:-horizon]
    mask = np.isfinite(past) & np.isfinite(fut)
    past=past[mask]; fut=fut[mask]
    # position = sign past if |past|>thr
    pos = np.where(past>thr, 1, np.where(past<-thr, -1, 0))
    pnl = np.mean(pos*fut) # avg per trade
    # hit rate
    active = np.sum(pos!=0)
    if active>0:
        avg = float(np.mean(pos[pos!=0]*fut[pos!=0]))
    else:
        avg=0
    corr = float(np.corrcoef(past, fut)[0,1]) if len(past)>10 else 0
    return avg, corr, active/len(past)

