def signal(obs):
    out = {}
    for a in ['A','B','C','IDX']:
        try:
            m = obs.hist(a, 'mid', 160)
        except Exception:
            continue
        if m is None or len(m) < 120:
            continue
        cur = m[-1]
        past = m[-101] if len(m) >= 101 else m[0]
        if not (cur == cur and past == past):
            continue
        ret = cur - past
        # normalize by vol proxy: mean abs diff?
        # simple threshold in cents
        thresh = {'A': 8.0, 'B': 5.0, 'C': 20.0, 'IDX': 8.0}[a]
        if ret > thresh:
            out[a] = 1.0
        elif ret < -thresh:
            out[a] = -1.0
        else:
            out[a] = 0.0
    return out

