def signal(obs):
    # Index arbitrage: IDX vs basket
    wA = 0.3333
    wB = 0.6667
    wC = 0.1667
    n = 200
    mids = {}
    for a in ['A','B','C','IDX']:
        mids[a] = obs.hist(a, 'mid', n)
    fair = wA*mids['A'] + wB*mids['B'] + wC*mids['C']
    idx = mids['IDX']
    diff = idx - fair
    valid = ~np.isnan(diff)
    if np.sum(valid) < 50:
        return {}
    mean = np.nanmean(diff)
    std = np.nanstd(diff)
    if std == 0 or np.isnan(std):
        return {}
    latest = diff[-1]
    if np.isnan(latest):
        return {}
    z = (latest - mean) / std
    thresh = 1.0
    targets = {}
    if abs(z) > thresh:
        scale = np.clip(abs(z)/3.0, 0, 1)
        sign = 1 if z > 0 else -1
        # IDX overpriced -> short IDX, long components
        targets['IDX'] = -sign * scale
        targets['A'] = sign * scale * 0.3333
        targets['B'] = sign * scale * 0.6667
        targets['C'] = sign * scale * 0.1667
    return targets

