        d = h[-1] - h[-31]
        if d > 18:
            targets['C.X'] = 1.0
        elif d < -18:
            targets['C.X'] = -1.0
        else:
            targets['C.X'] = 0.0
    else:
        targets['C.X'] = 0.0
