        if r1 < -25:
            obs.state['c_hold'] = 5  # hold bounce for 5 steps
        elif r1 < -15 and obs.state['c_hold'] == 0:
            # smaller drop, smaller size, hold 3
            obs.state['c_hold'] = 3
            rev_signal = 0.5
        # manage hold
