                rev_signal = 1.0 if obs.state['c_hold'] >= 3 else 0.5
            obs.state['c_hold'] -= 1
        else:
            rev_signal = 0
    else:
        if obs.state['c_hold'] > 0:
            obs.state['c_hold'] -= 1
            rev_signal = 1.0
        else:
            rev_signal = 0
