def signal(obs):
    st = obs.state
    a = obs.last('A','mid'); b = obs.last('B','mid'); c = obs.last('C','mid'); idx = obs.last('IDX','mid')
    if a!=a or b!=b or c!=c or idx!=idx:
        return {}
    syn = 0.3333*a + 0.6667*b + 0.1667*c
    diff = idx - syn
    pos = st.get('pos', 0)
    # hysteresis: enter 22, exit 5
    if pos == 0:
        if diff > 22: pos = -1
        elif diff < -22: pos = 1
    elif pos == 1:
        if diff > -5: pos = 0
    elif pos == -1:
        if diff < 5: pos = 0
    st['pos'] = pos
    # pos = +1 means IDX cheap (diff negative) -> long IDX, short basket
    return {'IDX': float(pos), 'A': float(-pos*0.3333), 'B': float(-pos*0.6667), 'C': float(-pos*0.1667)}

