def signal(obs):
    n=80
    mC = obs.hist('C','mid',n+12)
    if mC is None or len(mC)<n+12:
        return {}
    # fill nan
    for i in range(len(mC)):
        if mC[i]!=mC[i]:
            if i>0: mC[i]=mC[i-1]
    for i in range(len(mC)-1,-1,-1):
        if mC[i]!=mC[i]:
            j=i+1
            while j<len(mC) and mC[j]!=mC[j]: j+=1
            if j<len(mC): mC[i]=mC[j]
    # compute 10-step return
    ret10 = mC[-1] - mC[-11]
    # compute rolling std of ret10 over last 80
    rets=[]
    for i in range(10, len(mC)):
        rets.append(mC[i]-mC[i-10])
    tail=rets[-80:]
    s=0.0
    for v in tail: s+=v
    mu=s/len(tail)
    var=0.0
    for v in tail: var+=(v-mu)*(v-mu)
    sd=(var/len(tail))**0.5
    if sd<4: sd=4
    z=ret10/sd
    if abs(z)<1.2:
        return {'C':0}
    if z>3: z=3
    if z<-3: z=-3
    # mean revert
    sig = -z*0.3
    if sig>0.9: sig=0.9
    if sig<-0.9: sig=-0.9
    return {'C':sig, 'C.X':0,'A':0,'B':0,'IDX':0,'A.X':0,'B.X':0}

