def corr(x,y):
    m = np.isfinite(x) & np.isfinite(y)
    x=x[m]; y=y[m]
    if len(x)<100: return float('nan')
    xm=float(np.mean(x)); ym=float(np.mean(y))
    num=float(np.sum((x-xm)*(y-ym)))
    den=float(math.sqrt(np.sum((x-xm)**2)*np.sum((y-ym)**2)))
    return num/den if den!=0 else float('nan')

