def ic(asset, look, fwd):
    m = H[asset]['mid']
    n = len(m)-look-fwd
    if n<200:
        return float('nan'),0
    p = m[look:look+n] - m[0:n]
    fut = m[look+fwd:look+fwd+n] - m[look:look+n]
    valid = ~(np.isnan(p) | np.isnan(fut))
    pv = p[valid]; fv = fut[valid]
    if len(pv)<200:
        return float('nan'),0
    c = float(np.corrcoef(pv, fv)[0,1])
    return c, int(valid.sum())

