def zscore_stats(base,x,window=200,threshold=1.0):
    mid_a = H[base]['mid']
    mid_x = H[x]['mid']
    spread = mid_a - mid_x
    n = len(spread)
    z = np.full(n, np.nan)
    # rolling mean/std
    for i in range(window, n):
        vals = spread[i-window:i]
        if np.isnan(vals).any():
            continue
        mean = float(np.mean(vals))
        std = float(np.std(vals))
        if std > 1e-9:
            z[i] = (spread[i] - mean)/std
    ret_a = np.diff(mid_a)
    ret_x = np.diff(mid_x)
    pnl = []
    for i in range(window, n-1):
        zi = z[i]
        if np.isnan(zi):
            continue
        if abs(zi) > threshold:
            sig = 1 if zi>0 else -1
            # short base, long x if spread high (base expensive)
            pos_base = -sig
            pos_x = sig
            ra = ret_a[i]
            rx = ret_x[i]
            if np.isnan(ra) or np.isnan(rx):
                continue
            pnl.append(pos_base*ra + pos_x*rx)
    pnl = np.array(pnl)
    if len(pnl)==0:
        return {'mean_pnl_per_step': np.nan, 'std_pnl': np.nan, 'sharpe': np.nan, 'trades':0}
    mean_pnl = float(np.mean(pnl))
    std_pnl = float(np.std(pnl))
    sharpe = mean_pnl/std_pnl if std_pnl>0 else float('nan')
    return {'mean_pnl_per_step': mean_pnl, 'std_pnl': std_pnl, 'sharpe': sharpe, 'trades': int(len(pnl))}

