def ar1_stats(asset1, asset2):
    d = H[asset1]['mid'] - H[asset2]['mid']
    d = d[~np.isnan(d)]
    x = d[:-1]; y = d[1:]
    mean_x = np.mean(x); mean_y = np.mean(y)
    cov = np.mean((x-mean_x)*(y-mean_y))
