        h=obs.hist(asset,'mid',look+1)
        if h is None or len(h) < look+1:
            return None
        a=float(h[-1]); b=float(h[-look-1])
        if a!=a or b!=b:
            return None
        return a-b
    # A dual-confirmed momentum thr30
    pA=past('A',30)
    pAX=past('A.X',30)
    sigA=0.0
    if pA is not None and pAX is not None:
        if pA>30 and pAX>30:
            sigA=1.0
        elif pA<-30 and pAX<-30:
            sigA=-1.0
    targets['A']=float(sigA)
    # C.X dual-confirmed thr30
    pC=past('C',30)
    pCX=past('C.X',30)
    sigCX=0.0
    if pC is not None and pCX is not None:
        if pC>30 and pCX>30:
            sigCX=1.0
        elif pC<-30 and pCX<-30:
            sigCX=-1.0
    elif pCX is not None:
        if pCX>30:
            sigCX=1.0
        elif pCX<-30:
            sigCX=-1.0
    targets['C.X']=float(sigCX)
    # IDX basket reversion with hysteresis via state
    if 'idx_pos' not in obs.state:
        obs.state['idx_pos']=0.0
    try:
        mA=obs.last('A','mid')
        mB=obs.last('B','mid')
        mC=obs.last('C','mid')
