def simulate(thr_entry, thr_exit):
    # simulate simple state: position -1,0,1 based on diff with hysteresis
    pos=0
    pnls=[]
    # we step every 10 steps as signal runs
    for i in range(0, n-50, 10):
        a=midA[i]; b=midB[i]; cc=midC[i]; idx=midIDX[i]
        if a!=a or b!=b or cc!=cc or idx!=idx:
            continue
        syn=0.3333*a+0.6667*b+0.1667*cc
        diff=idx-syn
        if diff > thr_entry:
            pos=-1
        elif diff < -thr_entry:
            pos=1
        elif abs(diff) < thr_exit:
            pos=0
        # forward 50
        idx2=midIDX[i+50]
        if idx2!=idx2:
            continue
        fwd=idx2-idx
        pnls.append(pos*fwd)
    arr=np.array(pnls)
    if len(arr)==0:
        return (0,0,0)
    gross=float(np.sum(arr))
    mean=float(np.mean(arr))
    # hit rate: profitable trades only when pos !=0
    # compute sharpe approx: mean/std * sqrt(??)
    std=float(np.std(arr))
    sharpe=mean/(std+1e-9)* ( (15750/10)**0.5 ) if std>0 else 0
    # count trades (entries)
    return (round(gross,1), round(mean,2), round(sharpe,2), len(arr))

