        if any(x!=x for x in [a,b,cc,idx,a2,b2,cc2,idx2]):
            continue
        syn=0.3333*a+0.6667*b+0.1667*cc
        syn2=0.3333*a2+0.6667*b2+0.1667*cc2
        diff=idx-syn
        if diff > thr_entry:
            pos=-1
