# Let's compute net assuming 0.5 spread per leg

def signal(obs):
    targets={}
    if 'pos' not in obs.state:
        obs.state['pos']=0.0
    try:
        mA=obs.last('A','mid'); mB=obs.last('B','mid'); mC=obs.last('C','mid'); midx=obs.last('IDX','mid')
        if mA==mA and mB==mB and mC==mC and midx==midx:
            syn=0.3333*mA+0.6667*mB+0.1667*mC
            diff=midx-syn
            if diff < -15:
                obs.state['pos']=1.0
            elif diff > 15:
                obs.state['pos']=-1.0
            elif abs(diff) < 5:
                obs.state['pos']=0.0
    except: pass
    targets['IDX']=float(obs.state['pos'])*0.5
    targets['A']=0.0; targets['A.X']=0.0; targets['B']=0.0; targets['B.X']=0.0; targets['C']=0.0; targets['C.X']=0.0
    return targets

