def signal(obs):
    targets = {}
    pairs = [('A','A.X'), ('B','B.X'), ('C','C.X')]
    n_hist = 400
    thresh = 1.8
    for a1,a2 in pairs:
        try:
            m1 = obs.last(a1,'mid')
            m2 = obs.last(a2,'mid')
            if m1 is None or m2 is None or np.isnan(m1) or np.isnan(m2):
                continue
            h1 = obs.hist(a1,'mid', n_hist)
            h2 = obs.hist(a2,'mid', n_hist)
            if len(h1) < 50 or len(h2) < 50:
                continue
            diff = h1 - h2
            # drop nan
            valid = ~np.isnan(diff)
            diff_valid = diff[valid]
            if len(diff_valid) < 50:
                continue
            mean = float(np.mean(diff_valid))
            std = float(np.std(diff_valid))
            if std <= 1e-9:
                continue
            d = float(m1 - m2)
            z = (d - mean)/std
            if z > thresh:
                # a1 expensive -> short a1, long a2
                targets[a1] = targets.get(a1,0.0) - 1.0
                targets[a2] = targets.get(a2,0.0) + 1.0
            elif z < -thresh:
                targets[a1] = targets.get(a1,0.0) + 1.0
                targets[a2] = targets.get(a2,0.0) - 1.0
            # else no trade
        except Exception:
            continue
    # clip
    out = {}
    for k,v in targets.items():
        if v > 1.0:
            v = 1.0
        elif v < -1.0:
            v = -1.0
        out[k] = v
    return out

