    a = obs.last('A', 'mid')
    b = obs.last('B', 'mid')
    c = obs.last('C', 'mid')
    i = obs.last('IDX', 'mid')
    if not (a==a and b==b and c==c and i==i):
        return {}
    prem = i - (0.3333*a + 0.6667*b + 0.1667*c)
    pos = st.get('pos', 0)
    if prem > 60:
        pos = -1
    elif prem < -60:
        pos = 1
    elif abs(prem) < 20:
        pos = 0
    st['pos'] = pos
    return {'IDX': float(pos)}

def signal(obs):
    st = obs.state
    W = 500
    a = obs.hist('A', 'mid', W+5)
    b = obs.hist('B', 'mid', W+5)
    c = obs.hist('C', 'mid', W+5)
    d = obs.hist('IDX', 'mid', W+5)
    if len(d) < W:
        return {}
    n = len(d)
    prem = [0.0]*n
    for k in range(n):
        x1=a[k]; x2=b[k]; x3=c[k]; x4=d[k]
        if x1==x1 and x2==x2 and x3==x3 and x4==x4:
            prem[k]=x4-(0.3333*x1+0.6667*x2+0.1667*x3)
        else:
            prem[k]=float('nan')
    # rolling mean/std over last W
    s=0.0; s2=0.0; cnt=0
    for k in range(n-W, n):
        v=prem[k]
        if v==v:
            s+=v; s2+=v*v; cnt+=1
    if cnt < W*0.9:
        return {}
    m=s/cnt
    v=s2/cnt-m*m
    sd=v**0.5 if v>0 else 1.0
    if sd<5: sd=5.0
    z=(prem[n-1]-m)/sd
    pos=st.get('pos',0)
    if z>1.5: pos=-1
    elif z<-1.5: pos=1
    elif abs(z)<0.5: pos=0
    st['pos']=pos
    return {'IDX': float(pos)}
